import React from 'react';
import { TextField, Checkbox, FormControlLabel, Typography } from '@mui/material';
import SearchableDropdown from '../Common/SearchableDropdown/SearchableDropdown.tsx';

interface Props {
    param: any;
    index: number;
    errorMessage?: string;
    onChange: (index: number, value: any) => void;
    statusList: any;
}

const DynamicFieldRenderer: React.FC<Props> = ({
    param,
    index,
    errorMessage,
    onChange,
    statusList
}) => {
    const keyType = param?.field?.key_type;

    const handleChange = (value: any) => {
        onChange(index, value);
    };

    // 🔹 DROPDOWN / RADIO / ENTITY
    if (['DROPDOWN', 'RADIO', 'ENTITY'].includes(keyType)) {

        let options: any[] = [];
        // ✅ 1. STATUS
        if (param?.field?.statusOption === 'is_status') {

            const requiredType = param?.field?.key_name;

            options = (statusList || [])
                .filter((item: any) =>
                    item?.active &&
                    item?.type_of_status === requiredType
                )
                .map((item: any) => ({
                    label: item.status_name,
                    value: item.status_id,
                }));
        }

        // ✅ 2. SUB STATUS
        else if (param?.field?.statusOption === 'is_sub_status') {

            const requiredType = param?.field?.key_name;

            const parentStatus = (statusList || []).find(
                (item: any) =>
                    item?.active &&
                    item?.type_of_status === requiredType
            );

            options = (parentStatus?.substatuses || []).map((sub: any) => ({
                label: sub.name,
                value: sub.name,
            }));
        }

        // ✅ 3. NORMAL DROPDOWN
        else {
            options = (param?.field?.key_options || []).map((opt: any) => ({
                label: opt,
                value: opt,
            }));
        }

        return (
            <SearchableDropdown
                label="Value"
                options={options}
                value={
                    options.find((opt) => opt.value === param.value) || null
                }
                onChange={(val: any) => handleChange(val?.value || '')}
                size="small"
                error={!!errorMessage}
                errorMessage={errorMessage}
            />
        );
    }

    // 🔹 CHECKBOX / BOOLEAN
    if (['CHECKBOX', 'BOOLEAN'].includes(keyType)) {
        return (
            <FormControlLabel
                control={
                    <Checkbox
                        checked={!!param.value}
                        onChange={(e) => handleChange(e.target.checked)}
                    />
                }
                label="Value"
            />
        );
    }

    // 🔹 TEXTAREA
    if (keyType === 'TEXTAREA') {
        return (
            <TextField
                fullWidth
                multiline
                rows={3}
                size="small"
                label="Value"
                value={param.value || ''}
                onChange={(e) => handleChange(e.target.value)}
                error={!!errorMessage}
                helperText={errorMessage}
            />
        );
    }

    // 🔹 DATE
    if (keyType === 'DATE') {
        return (
            <TextField
                fullWidth
                type="date"
                size="small"
                label="Value"
                InputLabelProps={{ shrink: true }}
                value={param.value || ''}
                onChange={(e) => handleChange(e.target.value)}
                error={!!errorMessage}
                helperText={errorMessage}
            />
        );
    }

    // 🔹 TIME
    if (keyType === 'TIME') {
        return (
            <TextField
                fullWidth
                type="time"
                size="small"
                label="Value"
                InputLabelProps={{ shrink: true }}
                value={param.value || ''}
                onChange={(e) => handleChange(e.target.value)}
                error={!!errorMessage}
                helperText={errorMessage}
            />
        );
    }

    // 🔹 NUMBER TYPES
    if (['INT', 'FLOAT'].includes(keyType)) {
        return (
            <TextField
                fullWidth
                type="number"
                size="small"
                label="Value"
                value={param.value || ''}
                onChange={(e) => handleChange(e.target.value)}
                error={!!errorMessage}
                helperText={errorMessage}
            />
        );
    }

    // 🔹 EMAIL
    if (keyType === 'EMAIL') {
        return (
            <TextField
                fullWidth
                type="email"
                size="small"
                label="Email"
                value={param.value || ''}
                onChange={(e) => handleChange(e.target.value)}
                error={!!errorMessage}
                helperText={errorMessage}
            />
        );
    }

    // 🔹 PHONE / PINCODE
    if (['PHONE', 'PINCODE'].includes(keyType)) {
        return (
            <TextField
                fullWidth
                type="tel"
                size="small"
                label="Value"
                value={param.value || ''}
                onChange={(e) => handleChange(e.target.value)}
                error={!!errorMessage}
                helperText={errorMessage}
            />
        );
    }

    // 🔹 FILE
    if (keyType === 'FILE') {
        return (
            <>
                <TextField
                    fullWidth
                    type="file"
                    size="small"
                    onChange={(e: any) => handleChange(e.target.files[0])}
                    error={!!errorMessage}
                    helperText={errorMessage}
                />

                {/* 👇 show selected file */}
                {param.value && (
                    <Typography variant="caption">
                        {typeof param.value === 'string'
                            ? param.value
                            : param.value.name}
                    </Typography>
                )}
            </>
        );
    }

    // 🔹 DEFAULT (STRING, CUSTOM, CITY etc.)
    return (
        <TextField
            fullWidth
            size="small"
            label="Value"
            value={param.value || ''}
            onChange={(e) => handleChange(e.target.value)}
            error={!!errorMessage}
            helperText={errorMessage}
        />
    );
};

export default DynamicFieldRenderer;